                if (isSentinel) {
                  return [
                    none<MinimumQuoteTokenThreshold>(),
                    offset + fixedSize,
                  ] as [Option<MinimumQuoteTokenThreshold>, number];
                }
                const [value, newOffset] = inner.deserialize(bytes, offset);
                return [some(value), newOffset] as [
                  Option<MinimumQuoteTokenThreshold>,
                  number,
                ];
